    'about.eyebrow': 'Hakkımızda — Darwesh Group',
    'about.heroTitle': 'Doğrulayabileceğiniz emlaklar, güvenebileceğiniz insanlar.',
    'about.heroSubtitle': 'Darwesh Group, Kürdistan Bölgesi\'ndeki alıcıları, kiracıları ve emlak danışmanlarını; doğrulanmış ilanlar, yerel uzmanlık ve daha fazla şeffaflığı hak eden bir piyasa için tasarlanmış araçlarla bir araya getiriyor.',
    'about.storyEyebrow': 'Hikayemiz',
    'about.storyTitle': 'Hızla hareket eden ve daha iyi bilgiye ihtiyaç duyan bir piyasa için inşa edildi.',
    'about.storyBody1': 'Darwesh Group basit bir hayal kırıklığıyla başladı: Kürdistan\'da güvenilir bir emlak ilanı bulmak, ağızdan ağıza dolaşan bilgilere, yanıtsız kalan aramalara ve emlakla uyuşmayan fotoğraflara güvenmek anlamına geliyordu. Biz bunu düzeltmeye karar verdik — her seferinde tek bir doğrulanmış ilan, tek bir dürüst konuşmayla.',
    'about.storyBody2': 'Bugün platformumuz emlak danışmanlarını, mülk sahiplerini ve alıcıları tek bir çatı altında bir araya getiriyor — Firestore destekli gerçek ilanlar, taleplerin canlı takibi ve insanların akıllıca arama yapmasına yardımcı olan MAM AI ile. Yayınladığımız her özellik tek bir soruyu yanıtlamalı: Bu, süreci daha dürüst hale mi getiriyor?',
    'about.valuesEyebrow': 'İnandıklarımız',
    'about.valuesTitle': 'Asla taviz vermediğimiz dört ilke',
    'about.value1Title': 'Doğrulanmış İlanlar',
    'about.value1Body': 'Platformumuza ulaşan her emlak, yayımlanmadan önce incelenir; böylece gördüğünüz şey gerçekten var olandır.',
    'about.value2Title': 'Yerel Uzmanlık',
    'about.value2Body': 'Danışmanlarımız, ilan verdikleri mahallelerde yaşayıp çalışır — Erbil\'den Zaxo\'ya kadar — ve her sokağı tanır.',
    'about.value3Title': 'Önce İnsan',
    'about.value3Body': 'İlk aramanızdan son imzaya kadar, ekibimizden gerçek bir kişi süreç boyunca yanınızda olur.',
    'about.value4Title': 'Akıllı Araçlar',
    'about.value4Body': 'Gayrimenkul bilgilerini açık bir şekilde düzenliyoruz, böylece karar vermek daha kolay olur.',
    'about.citiesEyebrow': 'Nerede faaliyet gösteriyoruz',
    'about.citiesTitle': 'Kürdistan Bölgesi\'nin tamamında aktifiz',
